export function getWordsByCategory(category: VocabularyCategory): VocabularyWord[] {
  return quranVocabulary.filter(w => w.category === category);
}

export function getCategoryInfo(category: VocabularyCategory): VocabularyCategoryInfo {
  return vocabularyCategories.find(c => c.id === category)!;
}

export function getWordById(id: number): VocabularyWord | undefined {
  return quranVocabulary.find(w => w.id === id);
}

export function searchVocabulary(query: string): VocabularyWord[] {
  const q = query.toLowerCase();
  return quranVocabulary.filter(w =>
    w.arabic.includes(q) ||
    w.transliteration.toLowerCase().includes(q) ||
    w.french.toLowerCase().includes(q)
  );
}

export function getRandomWords(count: number, excludeIds: number[] = []): VocabularyWord[] {
  const available = quranVocabulary.filter(w => !excludeIds.includes(w.id));
  const shuffled = [...available].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count);
}
